ssion\'s meta data'=>'Мета подаци слања','Link to the post editing page for submission %d'=>'Веза ка страници за уређивање чланка за слање %d','Submission Key'=>'Кључ слања','Submitted at'=>'Послато','Original Form ID'=>'ИБ изворног обрасца','Loading Form'=>'Учитавање обрасца','This form has no submissions.'=>'Овај образац нема слања.','%d submission in the form'=>'%d слање у обрасцу' . "\0" . '%d слања у обрасцу' . "\0" . '%d слања у обрасцу','%d submission filtered'=>'Филтрирано је %d слање' . "\0" . 'Филтрирана су %d слања' . "\0" . 'Филтрирано је %d слања','Navigate to first page'=>'Иди на прву страницу','Navigate to previous page'=>'Иди на претходну страницу','Navigate to next page'=>'Иди на следећу страницу','Navigate to last page'=>'Иди на последњу страницу','Page %1$d of %2$d'=>'Страница %1$d од %2$d','Go to page:'=>'Иди на страницу:','Select the page number to navigate to'=>'Изаберите број странице на коју желите да одете','Set number of submissions to display per page.'=>'Подесите број слања која се приказују по страници.','Show %d'=>'Прикажи %d','Display Columns control'=>'Управљање приказом колона','Unselect to hide corresponding column'=>'Уклоните ознаку да бисте сакрили одговарајућу колону','No Submissions matching the request.'=>'Нема слања која одговарају захтеву.','Submissions Status'=>'Стање слања','Enter Search Term...'=>'Унесите појам за претрагу…','Filter Submissions'=>'Филтрирај слања','Reset Filters'=>'Врати филтере на почетно','Submission successfully exported'=>'Слање је успешно извезено','The export failed. Contact a developer or check the logs if this failure persists.'=>'Извоз није успео. Обратите се програмеру или прочитајте дневнике ако се овај неуспех понавља.','Export submission %d via CSV file'=>'Извези слање %d у CSV датотеку','Move submission %d to the Trash'=>'Премести слање %d на отпад','Delete Submission %d'=>'Избриши слање %d','Delete Submission Permanently'=>'Трајно избриши слање','Restore submission %d'=>'Врати слање %d']];